'use strict';
let publication={published:false},publicationWorking=false,publicationAbort=null,publicationSnapshot=null;
const publishBox=document.createElement('section');publishBox.className='publication-box';publishBox.innerHTML=`<p class="eyebrow">TAKE YOUR WORK INTO THE WORLD</p><h3>Your portfolio. One link.</h3><p>Publish selected photos and videos to a web page anyone with the link can open. Your draft stays private until you publish.</p><div id="publication-state" role="status">Checking your published portfolio…</div><button type="button" id="publish-portfolio" class="button">Review & publish portfolio ↗</button><div id="published-controls" hidden><label>Your shareable link<input id="published-url" readonly></label><div class="publication-actions"><button type="button" class="outline" id="copy-portfolio-link">Copy link</button><a id="visit-public-portfolio" class="outline" target="_blank" rel="noopener">Open portfolio ↗</a><button type="button" class="subtle" id="unpublish-portfolio">Unpublish</button></div><p class="hint">Edits in the builder are private until you publish an update. Unpublishing disables the page and its online media; previously downloaded copies cannot be recalled.</p></div><p id="publication-feedback" role="status" aria-live="polite"></p>`;
document.querySelector('.export-box').before(publishBox);const publicationFeedback=document.querySelector('#publication-feedback');
const publishDialog=document.createElement('dialog');publishDialog.id='publish-dialog';publishDialog.setAttribute('aria-label','Review public portfolio');publishDialog.innerHTML=`<div class="publish-review"><p class="eyebrow">REVIEW BEFORE YOU SHARE</p><h2>Make your entrance.</h2><p id="publish-review-summary"></p><p>Your name, professional title, city, bio, experience, training and selected work will be visible to anyone with this link. Keep private details out of your bio and project credits.</p><fieldset><legend>Choose what else to share</legend><label class="publication-choice"><input type="checkbox" id="publish-contact"> Include email, phone and Instagram / portfolio contact</label><label class="publication-choice"><input type="checkbox" id="publish-stats"> Include model stats: height, measurements, hair and eyes</label></fieldset><label class="publication-choice" id="makeup-directory-option" hidden><input type="checkbox" id="publish-makeup-directory"> Request a listing in Find makeup artists. GLOSS reviews each published version before listing your name, city, specialties and portfolio link.</label><fieldset id="publish-work-options"><legend>Selected work</legend><div id="publish-media-choices"></div></fieldset><p class="hint">Your uploaded portrait is included. Publishing uploads the selected media to online storage. This page is not listed in a public directory, but anyone with the link can view or forward it.</p><p id="publish-progress" role="status" aria-live="polite"></p><div class="publication-actions"><button type="button" class="button" id="confirm-publish">Publish this portfolio ↗</button><button type="button" class="outline" id="cancel-publish">Cancel</button></div></div>`;document.body.append(publishDialog);
async function publicationRequest(path,options={}){const response=await fetch(path,{credentials:'same-origin',...options});const data=await response.json().catch(()=>({error:'The publishing service could not respond. Please try again.'}));if(!response.ok)throw Error(data.error||'Publishing could not be completed.');return data;}
function paintPublication(){document.querySelector('#publication-state').textContent=publication.published?'Live · Last published '+new Date(publication.updatedAt).toLocaleString():'Not published · Only your device draft is available';document.querySelector('#published-controls').hidden=!publication.published;document.querySelector('#publish-portfolio').textContent=publication.published?'Review & publish update ↗':'Review & publish portfolio ↗';document.querySelector('#published-url').value=publication.url||'';document.querySelector('#visit-public-portfolio').href=publication.url||'#';}
async function refreshPublication(){publication=await publicationRequest('/api/publication');paintPublication();}
refreshPublication().catch(error=>{document.querySelector('#publication-state').textContent=error.message;});
document.querySelector('#publish-portfolio').onclick=()=>{if(publicationWorking||mediaBusy||storageBusy){publicationFeedback.textContent='Please wait for the current upload or save to finish.';return;}if(!form.reportValidity())return;if(!state.name.trim()){publicationFeedback.textContent='Add your name in Details first.';return;}const work=state.media.filter(m=>m.role===state.role&&!m.sample);if(!work.length&&!hotelProfile()){publicationFeedback.textContent='Add at least one photo or video in Collections first.';return;}publicationSnapshot=structuredClone(state);document.querySelector("#makeup-directory-option").hidden=state.role!=="Makeup artist";document.querySelector("#publish-makeup-directory").checked=false;document.querySelector('#publish-review-summary').textContent=`${state.name} · ${state.role} · ${work.length} portfolio item${work.length>1?'s':''}`;document.querySelector('#publish-work-options').hidden=!work.length;document.querySelector('#publish-media-choices').innerHTML=work.map((m,i)=>`<label class="publication-choice"><input type="checkbox" data-public-media="${i}" checked><span>${E(m.title)}<small>${E(m.category)} · ${m.type==='video'?'Video':'Photo'}</small></span></label>`).join('');document.querySelector('#publish-progress').textContent='';document.querySelector('#confirm-publish').textContent=publication.published?'Publish this update ↗':'Publish this portfolio ↗';publishDialog.showModal();};
function publicationBusy(value){publicationWorking=value;document.querySelector('#confirm-publish').disabled=value;document.querySelector('#publish-portfolio').disabled=value;document.querySelector('#unpublish-portfolio').disabled=value;document.querySelector('#cancel-publish').textContent=value?'Cancel upload':'Cancel';publishDialog.querySelectorAll('input').forEach(input=>input.disabled=value);}
document.querySelector('#cancel-publish').onclick=()=>{if(publicationWorking){publicationAbort?.abort();return;}publishDialog.close();};publishDialog.addEventListener('cancel',event=>{if(publicationWorking){event.preventDefault();publicationAbort?.abort();}});
document.querySelector('#confirm-publish').onclick=async()=>{if(publicationWorking)return;const snapshot=publicationSnapshot,work=snapshot.media.filter(m=>m.role===snapshot.role&&!m.sample),selected=[...publishDialog.querySelectorAll('[data-public-media]:checked')].map(c=>work[Number(c.dataset.publicMedia)]);const hotel=Object.hasOwn(hotelRoles,snapshot.role)?hotelRoles[snapshot.role]:null;if(!selected.length&&!hotel){document.querySelector('#publish-progress').textContent='Select at least one photo or video.';return;}const profile={};for(const key of ['name','title','city','role','bio','specialty','experience','education','skills','template','languages','availability'])profile[key]=snapshot[key];if(hotel)for(const key of Object.keys(hotel.fields))profile[key]=snapshot[key];if(document.querySelector('#publish-contact').checked)for(const key of ['email','phone','link'])profile[key]=snapshot[key];if(document.querySelector('#publish-stats').checked)for(const key of ['height','measurements','hair','eyes'])profile[key]=snapshot[key];const makeupDirectoryRequested=profile.role==="Makeup artist"&&document.querySelector("#publish-makeup-directory").checked;if(makeupDirectoryRequested&&!profile.city.trim()){document.querySelector("#publish-progress").textContent="Add your city in Details before requesting a directory listing.";return;}let build;publicationAbort=new AbortController();publicationBusy(true);const progress=document.querySelector('#publish-progress');try{progress.textContent='Preparing selected media…';const files=[];if(snapshot.portrait&&!snapshot.portrait.startsWith('assets/')){const blob=await fetch(snapshot.portrait).then(r=>r.blob());files.push({id:crypto.randomUUID(),slot:'portrait',title:'Portrait',category:'Portrait',note:'',featured:false,blob});}for(const m of selected){const blob=await fetch(m.src).then(r=>r.blob());files.push({id:crypto.randomUUID(),slot:'work',title:m.title,category:m.category,note:m.note||'',featured:!!m.featured,blob});}if(publicationAbort.signal.aborted)throw new DOMException('Cancelled','AbortError');build=await publicationRequest('/api/publish/start',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({profile,makeupDirectoryRequested,assets:files.map(({blob,...a})=>({...a,mime:blob.type,size:blob.size}))}),signal:publicationAbort.signal});for(let i=0;i<files.length;i++){const file=files[i],target=build.assets.find(a=>a.id===file.id);progress.textContent=`Uploading ${i+1} of ${files.length}: ${file.title}`;await publicationRequest(target.uploadUrl,{method:'PUT',headers:{'content-type':file.blob.type},body:file.blob,signal:publicationAbort.signal});}progress.textContent='Publishing your page…';const result=await publicationRequest(`/api/publish/${build.revision}/finish`,{method:'POST',signal:publicationAbort.signal});publication={...publication,...result,id:build.id};paintPublication();publishDialog.close();publicationFeedback.textContent='Your portfolio is live. Copy the link below to share it.';}catch(error){let reconciled=false;if(build){try{const current=await publicationRequest('/api/publication');if(current.published&&current.revision===build.revision){publication=current;paintPublication();publishDialog.close();publicationFeedback.textContent='Your portfolio is live. Copy its link to share it.';reconciled=true;}}catch{}}if(!reconciled)progress.textContent=error.name==='AbortError'?'Upload cancelled. Your previously published portfolio, if any, has not changed.':error.message;}finally{publicationBusy(false);publicationAbort=null;}};
document.querySelector('#copy-portfolio-link').onclick=async()=>{try{await navigator.clipboard.writeText(publication.url);publicationFeedback.textContent='Link copied. Anyone with it can view your published portfolio.';}catch{document.querySelector('#published-url').select();publicationFeedback.textContent='Select and copy the link shown above.';}};
const unpublishReview=document.createElement('dialog');unpublishReview.id='unpublish-review';unpublishReview.setAttribute('aria-label','Confirm unpublishing');unpublishReview.innerHTML='<div class="publish-review"><h2>Take it offline?</h2><p>Your portfolio link and its online photos/videos will stop working. Your draft on this device will remain.</p><div class="publication-actions"><button class="button" type="button" id="confirm-unpublish">Unpublish portfolio</button><button class="outline" type="button" id="keep-published">Keep it live</button></div><p id="unpublish-progress" role="status"></p></div>';document.body.append(unpublishReview);
document.querySelector('#unpublish-portfolio').onclick=()=>{if(!publicationWorking&&publication.published)unpublishReview.showModal();};document.querySelector('#keep-published').onclick=()=>{if(!publicationWorking)unpublishReview.close();};unpublishReview.addEventListener('cancel',event=>{if(publicationWorking)event.preventDefault();});
document.querySelector('#confirm-unpublish').onclick=async()=>{if(publicationWorking)return;publicationBusy(true);document.querySelector('#confirm-unpublish').disabled=true;document.querySelector('#unpublish-progress').textContent='Taking your portfolio offline…';try{await publicationRequest('/api/publication/unpublish',{method:'POST'});publication.published=false;paintPublication();unpublishReview.close();publicationFeedback.textContent='Portfolio unpublished. Its public page and online media are no longer accessible. Your device draft is unchanged.';}catch(error){document.querySelector('#unpublish-progress').textContent=error.message;}finally{publicationBusy(false);document.querySelector('#confirm-unpublish').disabled=false;}};
window.addEventListener('beforeunload',event=>{if(publicationWorking){event.preventDefault();event.returnValue='';}});
